<style scoped lang="scss" src="./row.scss"></style>

<script>
import { Component, Vue, Prop } from "vue-property-decorator";
import { has } from "../../util/has";
import {
  RowMode,
  RowJustifyContent,
  RowJustifyContentValues,
  RowModeValues
} from "./row.constants";

const modeToClass = {
  [RowMode.DEFAULT]: "",
  [RowMode.GMS]: "Row_GMS"
}

@Component({
  components: {},
})
export default class Row extends Vue {
  @Prop({
    type: String,
    default: RowMode.DEFAULT, 
    validator: has(RowModeValues)
  })
  mode;

  @Prop({
    type: String,
    default: RowJustifyContent.LEFT,
    validator: has(RowJustifyContentValues)
  })
  justifyContent;

  get modeClass() {
    return modeToClass[this.mode];
  }

  get justifyContentClass() {
    return this.justifyContent;
  }
}
</script>

<template>
  <div :class="['Row', modeClass, justifyContentClass]">
    <slot />
  </div>
</template>
